import java.util.StringTokenizer;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.PriorityQueue;

public class Main {
    static class Edge {
        int to;
        int weight;
        int id;

        Edge(int to, int weight, int id) {
            this.to = to;
            this.weight = weight;
            this.id = id;
        }
    }

    static int E, R;
    static ArrayList<Edge>[] adj;
    static int[] edgeU, edgeV, edgeW;

    // Tarjan / DFS para encontrar pontes e componentes 2-aresta-conexas (ou ciclos)
    // O grafo é um cacto: cada estação pertence a no máximo um ciclo simples.
    // Portanto, cada ciclo tem um comprimento bem definido.
    static int[] dfn, low;
    static int timer = 0;
    static int[] parentEdge;
    static int[] parentNode;
    static int[] cycleId; // cycleId de cada vértice (0 se não estiver em ciclo)
    static int cycleCount = 0;
    static long[] cycleLength; // comprimento de cada ciclo

    static void findCycles(int u, int pEdge) {
        dfn[u] = low[u] = ++timer;
        for (Edge e : adj[u]) {
            if (e.id == pEdge) continue;
            int v = e.to;
            if (dfn[v] != 0) {
                low[u] = Math.min(low[u], dfn[v]);
                if (dfn[v] < dfn[u]) {
                    // Encontrou um back-edge u -> v
                    cycleCount++;
                    long len = e.weight;
                    int curr = u;
                    cycleId[curr] = cycleCount;
                    while (curr != v) {
                        int pe = parentEdge[curr];
                        len += edgeW[pe];
                        curr = parentNode[curr];
                        cycleId[curr] = cycleCount;
                    }
                    cycleLength[cycleCount] = len;
                }
            } else {
                parentNode[v] = u;
                parentEdge[v] = e.id;
                findCycles(v, e.id);
                low[u] = Math.min(low[u], low[v]);
            }
        }
    }

    static class State implements Comparable<State> {
        int u;
        long dist;

        State(int u, long dist) {
            this.u = u;
            this.dist = dist;
        }

        @Override
        public int compareTo(State o) {
            return Long.compare(this.dist, o.dist);
        }
    }

    static long dijkstra(int start, long T) {
        long[] dist = new long[E + 1];
        Arrays.fill(dist, Long.MAX_VALUE);
        PriorityQueue<State> pq = new PriorityQueue<>();

        dist[start] = 0;
        pq.add(new State(start, 0));

        long ans = Long.MAX_VALUE;

        while (!pq.isEmpty()) {
            State cur = pq.poll();
            int u = cur.u;
            long d = cur.dist;

            if (d > dist[u]) continue;

            if (cycleId[u] != 0) {
                long cLen = cycleLength[cycleId[u]];
                if (cLen >= T) {
                    long total = 2 * d + cLen;
                    if (total < ans) {
                        ans = total;
                    }
                }
            }

            for (Edge e : adj[u]) {
                int v = e.to;
                if (dist[v] > d + e.weight) {
                    dist[v] = d + e.weight;
                    pq.add(new State(v, dist[v]));
                }
            }
        }

        return ans == Long.MAX_VALUE ? -1 : ans;
    }

