                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) {
        FastReader sc = new FastReader();
        String tokenE = sc.next();
        if (tokenE == null) return;
        E = Integer.parseInt(tokenE);
        R = sc.nextInt();

        adj = new ArrayList[E + 1];
        for (int i = 1; i <= E; i++) {
            adj[i] = new ArrayList<>();
        }

        edgeU = new int[R + 1];
        edgeV = new int[R + 1];
        edgeW = new int[R + 1];

        for (int i = 1; i <= R; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            int w = sc.nextInt();
            edgeU[i] = u;
            edgeV[i] = v;
            edgeW[i] = w;
            adj[u].add(new Edge(v, w, i));
            adj[v].add(new Edge(u, w, i));
        }

        dfn = new int[E + 1];
        low = new int[E + 1];
        parentEdge = new int[E + 1];
        parentNode = new int[E + 1];
        cycleId = new int[E + 1];
        cycleLength = new long[E + 1];

        for (int i = 1; i <= E; i++) {
            if (dfn[i] == 0) {
                findCycles(i, 0);
            }
        }

        int K = sc.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < K; i++) {
            int X = sc.nextInt();
            long T = sc.nextLong();
            long res = dijkstra(X, T);
            sb.append(res).append("\n");
        }
        System.out.print(sb);
    }
}
